-- Esquema do banco HSQLDB do ReMoto legado (WebContent/db/remoto.script), sem a tabela USER
-- e sem chaves estrangeiras. Usado só para reconstruir a Configuration do código original
-- em memória, a partir de um cenário JSON.
SET DATABASE SQL NAMES FALSE
SET DATABASE SQL REFERENCES FALSE
SET DATABASE SQL SIZE FALSE
SET DATABASE SQL TYPES FALSE
SET DATABASE SQL TDC DELETE TRUE
SET DATABASE SQL TDC UPDATE TRUE
SET DATABASE SQL TRANSLATE TTI TYPES TRUE
SET DATABASE SQL CONCAT NULLS TRUE
SET DATABASE SQL UNIQUE NULLS TRUE
SET DATABASE SQL CONVERT TRUNCATE TRUE
SET DATABASE SQL DOUBLE NAN TRUE
SET DATABASE SQL LONGVAR IS LOB FALSE
CREATE MEMORY TABLE CATEGORY(CD_CATEGORY VARCHAR(20) NOT NULL PRIMARY KEY,NM_CATEGORY VARCHAR(30))
CREATE MEMORY TABLE NUCLEUS(CD_NUCLEUS VARCHAR(10) NOT NULL PRIMARY KEY,NM_NUCLEUS VARCHAR(30),LAYER VARCHAR(3),INDEX INTEGER,JOINT VARCHAR(30))
CREATE MEMORY TABLE JOINTS(CD_JOINT VARCHAR(10) NOT NULL PRIMARY KEY,NM_JOINT VARCHAR(30),NUM_NUCLEI INTEGER,INDEX INTEGER)
CREATE MEMORY TABLE CONFIGURATION(ID_CONFIGURATION INTEGER NOT NULL PRIMARY KEY,CD_USER VARCHAR(20),NM_CONFIGURATION VARCHAR(60),DS_CONFIGURATION VARCHAR(610),DT_CONFIGURATION TIMESTAMP,TFIN NUMERIC(128,4),STEP NUMERIC(128,4),MERGE INTEGER,KEEP_PROPERTIES INTEGER,STORE_RESULTS INTEGER,STORE_SIGNALS INTEGER)
CREATE MEMORY TABLE MISCELLANEOUS(PROPERTY VARCHAR(30) NOT NULL,ID_CONFIGURATION INTEGER NOT NULL,DESCRIPTION VARCHAR(100),VALUE NUMERIC(128,4),INDEX INTEGER,DIVISION INTEGER,PRIMARY KEY(PROPERTY,ID_CONFIGURATION))
CREATE MEMORY TABLE NERVE(CD_NERVE VARCHAR(20) NOT NULL,CD_JOINT VARCHAR(20) NOT NULL,ID_CONFIGURATION INTEGER NOT NULL,STIMULUS_SPINAL_ENTRY NUMERIC(128,4),STIMULUS_END_PLATE NUMERIC(128,4),ACTIVE INTEGER,INDEX INTEGER,START NUMERIC(128,4),STOP NUMERIC(128,4),PEAK NUMERIC(128,4),FREQUENCY NUMERIC(128,4),CD_SIGNAL VARCHAR(10),TINI NUMERIC(128,4),TFIN NUMERIC(128,4),AMP NUMERIC(128,4),FREQ NUMERIC(128,4),WIDTH NUMERIC(128,4),DELAY NUMERIC(128,4),PRIMARY KEY(CD_NERVE,ID_CONFIGURATION))
CREATE MEMORY TABLE HILL_TYPE_MUSCULOTENDON_PARAMETERS(ID_CONFIGURATION INTEGER NOT NULL,CD_MUSCLE VARCHAR(20) NOT NULL,OPTIMAL_LENGTH NUMERIC(128,4),VISCOSITY_COEFICIENT NUMERIC(128,4),ELASTIC_COEF_PARALLEL NUMERIC(128,4),C_T NUMERIC(128,4),K_T NUMERIC(128,4),LR_T NUMERIC(128,4),PENNATION_ANGLE NUMERIC(128,4),SLACK_TENDON_LENGTH NUMERIC(128,4),MAXIMUM_MUSCLE_FORCE NUMERIC(128,4),MUSCLE_MASS NUMERIC(128,4),INDEX INTEGER)
CREATE MEMORY TABLE NOTHING(ID_CONFIGURATION INTEGER NOT NULL,CD_MUSCLE VARCHAR(20) NOT NULL,OPTIMAL_LENGTH NUMERIC(128,4),VISCOSITY_COEFICIENT NUMERIC(128,4),ELASTIC_COEF_PARALLEL NUMERIC(128,4),C_T NUMERIC(128,4),K_T NUMERIC(128,4),LR_T NUMERIC(128,4),PENNATION_ANGLE NUMERIC(128,4),SLACK_TENDON_LENGTH NUMERIC(128,4),MAXIMUM_MUSCLE_FORCE NUMERIC(128,4),MUSCLE_MASS NUMERIC(128,4),INDEX INTEGER)
CREATE MEMORY TABLE CONDUCTANCE_TYPE(CD_CONDUCTANCE_TYPE VARCHAR(30) NOT NULL,ID_CONFIGURATION INTEGER NOT NULL,CD_NUCLEUS VARCHAR(10) NOT NULL,CD_NUCLEUS_PRE VARCHAR(10) NOT NULL,GMAX NUMERIC(128,4),E NUMERIC(128,4),CONNECTIVITY NUMERIC(128,4),DELAY NUMERIC(128,4),COMPARTMENT VARCHAR(1),ACTIVE INTEGER,INDEX INTEGER,PRIMARY KEY(CD_CONDUCTANCE_TYPE,ID_CONFIGURATION,CD_NUCLEUS,CD_NUCLEUS_PRE))
CREATE MEMORY TABLE NEURON_TYPE(CD_NEURON_TYPE VARCHAR(20) NOT NULL,ID_CONFIGURATION INTEGER NOT NULL,CD_NUCLEUS VARCHAR(10) NOT NULL,CD_NUCLEUS_PRE VARCHAR(10),CD_CATEGORY VARCHAR(20),THRESHOLD1 NUMERIC(128,4),THRESHOLD2 NUMERIC(128,4),AXON_VELOCITY1 NUMERIC(128,4),AXON_VELOCITY2 NUMERIC(128,4),AXON_THRESHOLD1 NUMERIC(128,4),AXON_THRESHOLD2 NUMERIC(128,4),RM_SOMA1 NUMERIC(128,4),RM_SOMA2 NUMERIC(128,4),RM_DEND1 NUMERIC(128,4),RM_DEND2 NUMERIC(128,4),D_DEND1 NUMERIC(128,4),D_DEND2 NUMERIC(128,4),L_DEND1 NUMERIC(128,4),L_DEND2 NUMERIC(128,4),D_SOMA1 NUMERIC(128,4),D_SOMA2 NUMERIC(128,4),L_SOMA1 NUMERIC(128,4),L_SOMA2 NUMERIC(128,4),CM NUMERIC(128,4),RI NUMERIC(128,4),TOTAL_AREA NUMERIC(128,4),DISTRIBUTION VARCHAR(2),CD_NERVE VARCHAR(20),MEAN INTEGER,STD INTEGER,QUANTITY INTEGER,ACTIVE INTEGER,INDEX INTEGER,THRESHOLDCA1 NUMERIC(128,4),THRESHOLDCA2 NUMERIC(128,4),PRIMARY KEY(CD_NEURON_TYPE,ID_CONFIGURATION,CD_NUCLEUS))
CREATE MEMORY TABLE MARKOV_TYPE(CD_MARKOV_TYPE VARCHAR(20) NOT NULL,ID_CONFIGURATION INTEGER NOT NULL,CD_NUCLEUS VARCHAR(10) NOT NULL,TPEAK NUMERIC(128,4),TMAX NUMERIC(128,4),ALPHA NUMERIC(128,4),BETA NUMERIC(128,4),GMAX NUMERIC(128,4),E NUMERIC(128,4),INDEX INTEGER NOT NULL,PRIMARY KEY(CD_MARKOV_TYPE,ID_CONFIGURATION,CD_NUCLEUS,INDEX))
CREATE MEMORY TABLE MOTORUNIT_TYPE(CD_MOTORUNIT_TYPE VARCHAR(20) NOT NULL,ID_CONFIGURATION INTEGER NOT NULL,CD_NUCLEUS VARCHAR(10) NOT NULL,TWITCH_TENSION1 NUMERIC(128,4),TWITCH_TENSION2 NUMERIC(128,4),TETANIC_TENSION1 NUMERIC(128,4),TETANIC_TENSION2 NUMERIC(128,4),TAU_FORCE1 NUMERIC(128,4),TAU_FORCE2 NUMERIC(128,4),AMP_EMG1 NUMERIC(128,4),AMP_EMG2 NUMERIC(128,4),DUR_EMG1 NUMERIC(128,4),DUR_EMG2 NUMERIC(128,4),INDEX INTEGER,PRIMARY KEY(CD_MOTORUNIT_TYPE,ID_CONFIGURATION,CD_NUCLEUS))
CREATE MEMORY TABLE SYNAPTIC_DYNAMICS(ID_CONFIGURATION INTEGER NOT NULL,CD_NUCLEUS VARCHAR(10) NOT NULL,CD_NUCLEUS_PRE VARCHAR(10) NOT NULL,CD_CONDUCTANCE_TYPE VARCHAR(20) NOT NULL,DYNAMIC_TYPE VARCHAR(2),TAU NUMERIC(128,4),VARIATION NUMERIC(128,4),PRIMARY KEY(ID_CONFIGURATION,CD_NUCLEUS,CD_NUCLEUS_PRE,CD_CONDUCTANCE_TYPE))
CREATE MEMORY TABLE MU_POSITION(CD_NUCLEUS VARCHAR(10) NOT NULL,CD_MU VARCHAR(10) NOT NULL,POSITION_Y NUMERIC(128,4),POSITION_Z NUMERIC(128,4),PRIMARY KEY(CD_NUCLEUS,CD_MU))
CREATE MEMORY TABLE INTERFACE_PARAMETERS(ID_CONFIGURATION INTEGER NOT NULL PRIMARY KEY,CD_NUCLEUS VARCHAR(10) NOT NULL)
CREATE MEMORY TABLE DESCENDING_COMMANDS(ID_CONFIGURATION INTEGER NOT NULL,CD_NUCLEUS VARCHAR(10) NOT NULL,CD_NEURON_TYPE VARCHAR(10) NOT NULL,CD_SIGNAL VARCHAR(10),MOD_TYPE VARCHAR(10),TINI NUMERIC(128,4),TFIN NUMERIC(128,4),AMP NUMERIC(128,4),FREQ NUMERIC(128,4),WIDTH NUMERIC(128,4),DELAY NUMERIC(128,4),PRIMARY KEY(ID_CONFIGURATION,CD_NUCLEUS,CD_NEURON_TYPE))
CREATE MEMORY TABLE INJECTED_CURRENT(ID_CONFIGURATION INTEGER NOT NULL,CD_NUCLEUS VARCHAR(10) NOT NULL,CD_NEURON_TYPE VARCHAR(20) NOT NULL,COMPARTMENT VARCHAR(1),IMAX NUMERIC(128,4),CD_SIGNAL VARCHAR(10),TINI NUMERIC(128,4),TFIN NUMERIC(128,4),AMP NUMERIC(128,4),FREQ NUMERIC(128,4),WIDTH NUMERIC(128,4),ACTIVE INTEGER,INDEX INTEGER,DELAY NUMERIC(128,4),PRIMARY KEY(ID_CONFIGURATION,CD_NUCLEUS,CD_NEURON_TYPE))
CREATE MEMORY TABLE SCENARIO_MODELS(ID_CONFIGURATION BIGINT NOT NULL,JOINT_MODEL VARCHAR(30) NOT NULL,MUSCLE_MODEL VARCHAR(30) NOT NULL,SPINDLE_MODEL VARCHAR(30) NOT NULL,GTO_MODEL VARCHAR(30) NOT NULL)
